sys_script_client.script:
function onLoad() {

    if (g_scratchpad.Sourcesystem == g_scratchpad.syspro_sourcesystem || g_scratchpad.Sourcesystem == g_scratchpad.syspro_sourcesystem_gcs) { // MSSCUSTODY-5521 - Added check for source system as GCS

        g_form.addInfoMessage('Time of the last refresh of holdings data - ' + g_scratchpad.LastPositionsRefreshDateTime);

    }
    //MSSCUSTODY-2986 -- New banner text for SWIFT refresh for custody Task

    var gr = new GlideAjax('MSSCustodyswifttext');
    gr.addParam('sysparm_name', 'apibannertext');
    gr.addParam('sysparm_trade_id', g_form.getValue('trade_id'));
    gr.getXML(resp);
    //MSSCUSTODY-2986 -- New banner text for SWIFT refresh for custody Task
}

function resp(response) {
    //MSSCUSTODY-2986 -- New banner text for SWIFT refresh for custody Task
    var answer = response.responseXML.documentElement.getAttribute("answer");
    if (answer == 'true') {
        g_form.addInfoMessage('SWIFT data refresh successful. No SWIFT messages available for this trade');
    }
    //MSSCUSTODY-2986 -- New banner text for SWIFT refresh for custody Task
}
